// checkTip relates the local ref to the tip the RSL records, which the
// server signed. A local ref behind the tip passes as behind: its state is an
// unskipped entry's record, which gittuf's full verification covered when
// gittufPassed is set.
func checkTip(ctx context.Context, st *store.Store, reader *rslread.Reader, ref string, gittufPassed bool, localTip func(string) (githash.Hash, error)) (Check, error) {
	c := Check{Name: CheckTip}

	if localTip == nil {
		c.Status, c.Detail = CheckSkip, "the local ref was not read"
		return c, nil
	}
	local, err := localTip(ref)
	if err != nil {
		return Check{}, fmt.Errorf("read the local ref: %w", err)
	}
	if len(local) == 0 {
		c.Status, c.Detail = CheckSkip, "the ref does not exist locally, so there is nothing to compare"
		return c, nil
	}

	rel, err := tipstate.Relate(ctx, st, reader, ref, local)
	if errors.Is(err, tipstate.ErrNoEntries) {
		c.Status, c.Detail = CheckFail, "every RSL entry for the ref is skipped, so no tip is recorded"
		return c, nil
	}
	if err != nil {
		return Check{}, err
	}

	c.Detail = rel.Describe()
	switch rel.Kind {
	case tipstate.Match:
		c.Status = CheckPass
	case tipstate.Behind:
		c.Status = CheckBehind
		if gittufPassed {
			c.Detail += ". gittuf verified the entries that record this state"
		}
	default:
		c.Status = CheckFail
	}
	return c, nil
}

