	if err != nil {
		return nil, nil, err
	}

	if path, err = filepath.Abs(path); err != nil {
		return nil, nil, err
	}

	var fs billy.Filesystem
	var fi os.FileInfo
	for {
		fs = osfs.New(path, osfs.WithBoundOS())

		pathinfo, err := fs.Stat("/")
		if !errors.Is(err, os.ErrNotExist) {
			if pathinfo == nil {
