// isAncestor reports whether ancestor is new or one of its ancestors.
func (g *Git) isAncestor(ctx context.Context, root, ancestor, commit string) (bool, error) {
	_, err := g.run(ctx, root, "merge-base", "--is-ancestor", ancestor, commit)
	if err == nil {
		return true, nil
	}
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
		return false, nil
	}
	return false, fmt.Errorf("compare %s with %s: %w", ancestor, commit, err)
}

// refs lists the refs under prefix with their object IDs, and which of them
// are symbolic.
func (g *Git) refs(ctx context.Context, root, prefix string) (map[string]string, map[string]bool, error) {
	out, err := g.run(ctx, root, "for-each-ref", "--format=%(refname) %(objectname) %(symref)", "--", prefix)
	if err != nil {
		return nil, nil, fmt.Errorf("list %s: %w", prefix, err)
	}

	refs := map[string]string{}
	symbolic := map[string]bool{}
	scanner := bufio.NewScanner(bytes.NewReader(out))
	for scanner.Scan() {
		fields := strings.Fields(scanner.Text())
		if len(fields) < 2 {
			continue
		}
		refs[fields[0]] = fields[1]
		if len(fields) > 2 {
			symbolic[fields[0]] = true
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, nil, fmt.Errorf("list %s: %w", prefix, err)
	}
	return refs, symbolic, nil
}

func (g *Git) run(ctx context.Context, root string, args ...string) ([]byte, error) {
	return g.runInput(ctx, root, "", args...)
}

// runInput runs git in root with the execution vectors of repository config
// neutralised, and returns its stdout.
func (g *Git) runInput(ctx context.Context, root, stdin string, args ...string) ([]byte, error) {
	// --no-replace-objects and an empty graft file make git read the stored
	// commit graph, so refs/replace/* or grafts cannot fake an ancestry.
	full := append([]string{
		"--no-replace-objects",
		"-C", root,
		"-c", "core.fsmonitor=false",
		"-c", "core.hooksPath=" + os.DevNull,
		"-c", "protocol.ext.allow=never",
		"-c", "fetch.writeCommitGraph=false",
	}, args...)

	cmd := exec.CommandContext(ctx, g.path, full...)
	cmd.Cancel = func() error { return interrupt(cmd.Process) }
	cmd.WaitDelay = waitDelay
	cmd.Env = append(os.Environ(), "GIT_GRAFT_FILE="+os.DevNull)
	if stdin != "" {
		cmd.Stdin = strings.NewReader(stdin)
	}
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr

	if err := cmd.Run(); err != nil {
		if ctx.Err() != nil {
			return nil, fmt.Errorf("git %s: %w", args[0], ctx.Err())
		}
		return nil, &RunError{Args: args[0], Err: err, Stderr: redact.URLs(strings.TrimSpace(stderr.String()))}
	}
	return stdout.Bytes(), nil
}
// Package gitcli runs the git binary safely: an absolute path resolved once,
// arguments as a slice with "--" before positionals, no shell, and an
// environment that cannot redirect git to another repository or make it run
// repository-configured programs.
package gitcli

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

// repoSelectors are inherited variables that would point git at a repository,
// index or object store other than the one entire-rsl opened.
var repoSelectors = []string{
	"GIT_DIR",
	"GIT_WORK_TREE",
	"GIT_INDEX_FILE",
	"GIT_OBJECT_DIRECTORY",
	"GIT_ALTERNATE_OBJECT_DIRECTORIES",
	"GIT_COMMON_DIR",
	"GIT_NAMESPACE",
}

// configOverrides neutralise repository config that makes git execute
// programs. They apply to every git process entire-rsl starts, including the
// ones gittuf starts.
var configOverrides = [][2]string{
	{"core.fsmonitor", "false"},
	{"core.hooksPath", os.DevNull},
}

// HardenProcessEnv removes repository selectors from the process environment
// and installs configOverrides through GIT_CONFIG_COUNT, replacing any
// environment-provided config. It runs once, at startup, before any git
// process can start: gittuf starts git itself and inherits this environment.
func HardenProcessEnv() error {
	for _, key := range repoSelectors {
		if err := os.Unsetenv(key); err != nil {
			return fmt.Errorf("unset %s: %w", key, err)
		}
	}

	for _, kv := range os.Environ() {
		key, _, _ := strings.Cut(kv, "=")
		if key == "GIT_CONFIG_PARAMETERS" || key == "GIT_CONFIG_COUNT" ||
			strings.HasPrefix(key, "GIT_CONFIG_KEY_") || strings.HasPrefix(key, "GIT_CONFIG_VALUE_") {
			if err := os.Unsetenv(key); err != nil {
				return fmt.Errorf("unset %s: %w", key, err)
			}
		}
	}

	for i, kv := range configOverrides {
		n := strconv.Itoa(i)
		if err := os.Setenv("GIT_CONFIG_KEY_"+n, kv[0]); err != nil {
			return fmt.Errorf("set git config override: %w", err)
		}
		if err := os.Setenv("GIT_CONFIG_VALUE_"+n, kv[1]); err != nil {
			return fmt.Errorf("set git config override: %w", err)
		}
	}
	if err := os.Setenv("GIT_CONFIG_COUNT", strconv.Itoa(len(configOverrides))); err != nil {
		return fmt.Errorf("set git config override: %w", err)
	}

	// Read the stored commit graph: no replacement objects, no grafts.
	for key, value := range map[string]string{"GIT_NO_REPLACE_OBJECTS": "1", "GIT_GRAFT_FILE": os.DevNull} {
		if err := os.Setenv(key, value); err != nil {
			return fmt.Errorf("set %s: %w", key, err)
		}
	}
	return nil
}
# Security Policy

We take security seriously at Entire. We appreciate your efforts to responsibly disclose vulnerabilities and will make every effort to acknowledge your contributions.

## Reporting a Vulnerability

**Please do not report security vulnerabilities through public GitHub issues.**

Instead, please send security-related reports to **[security@entire.io](mailto:security@entire.io)**.

### What to Include

When reporting a vulnerability, please include:

1. **Description** - A clear description of the vulnerability
2. **Impact** - What an attacker could achieve by exploiting this issue
3. **Steps to reproduce** - Detailed steps to reproduce the vulnerability
4. **Affected versions** - Which versions of entire-rsl are affected (if known)
5. **Suggested fix** - If you have ideas on how to fix it (optional)

### What to Expect

- **Acknowledgment** - We will acknowledge receipt of your report within 48 hours
- **Updates** - We will keep you informed of our progress as we investigate
- **Resolution** - We aim to resolve critical vulnerabilities within 90 days

## Confidentiality

**All reports will be kept confidential.** We will not share your information with third parties without your consent, except as required by law.

## Supported Versions

We recommend always running the latest version of entire-rsl.

## Scope

entire-rsl reports whether a repository's gittuf Reference State Log verifies. Its output is a security statement, so the following are in scope in particular:

- Any case where entire-rsl reports `verified` for a ref whose RSL history does not pass gittuf verification, has no applicable policy, or could not be fully evaluated
- Terminal escape or control sequences from repository data reaching the terminal through text output
- Any write to refs, objects or git config other than the remote-tracking RSL refs written by a confirmed fetch
- Argument or option injection into the git subprocesses entire-rsl runs

### Out of Scope

The following are generally not considered security vulnerabilities:

- Issues in third-party dependencies, including gittuf itself (please report these upstream)
- The contents of RSL custom fields, which entire-rsl labels as asserted and never uses for a verification outcome
- Social engineering attacks
- Denial of service attacks
- Issues requiring physical access to a user's device

---

Thank you for helping keep Entire and our community safe!
